/**
 * Swift Woo - Variation & Multi-Color Swatch JS
 * - 100% Native WooCommerce <select> & variations_form compatible (visually hidden)
 * - Auto-selects first in-stock variation on load
 * - Renders high-converting pill swatches with text, active checkmark & color dots
 * - Supports Bengali & English numerals (e.g. ১ পিস, ২ পিস, 1 Pcs, 2 Pcs)
 * - Dynamically generates multi-color selectors based on selected package/quantity
 * - Passes selected extra colors via hidden inputs -> saved to cart & order meta
 * - Triggers both DOM & jQuery change events for instant WooCommerce price/stock updates
 * - Scanner-safe, zero obfuscation, zero eval
 * @version 1.0.30
 */
( function () {
	'use strict';

	function initVariations() {
		const variationForm = document.querySelector( 'form.variations_form' );
		if ( ! variationForm ) return;

		// Bengali numeral normalizer
		function extractCount( val ) {
			if ( ! val ) return NaN;
			const bnMap = { '০': '0', '১': '1', '২': '2', '৩': '3', '৪': '4', '৫': '5', '৬': '6', '৭': '7', '৮': '8', '৯': '9' };
			const cleanStr = String( val ).replace( /[০-৯]/g, function ( d ) { return bnMap[ d ] || d; } );
			const match = cleanStr.match( /\d+/ );
			return match ? parseInt( match[ 0 ], 10 ) : NaN;
		}

		// Comprehensive color palette lookup (Bengali & English)
		const COLOR_PALETTE = {
			'black': '#111111', 'কালো': '#111111',
			'white': '#ffffff', 'সাদা': '#f7fafc',
			'red': '#e53e3e', 'লাল': '#e53e3e',
			'blue': '#2b6cb0', 'নীল': '#2b6cb0',
			'green': '#2f855a', 'সবুজ': '#2f855a',
			'yellow': '#ecc94b', 'হলুদ': '#ecc94b',
			'orange': '#dd6b20', 'কমলা': '#dd6b20',
			'pink': '#ed64a6', 'গোলাপী': '#ed64a6', 'গোলাপি': '#ed64a6',
			'purple': '#805ad5', 'বেগুনী': '#805ad5', 'বেগুনি': '#805ad5',
			'gray': '#718096', 'grey': '#718096', 'ধূসর': '#718096', 'ছাই': '#718096',
			'dark gray': '#4a5568', 'dark grey': '#4a5568', 'ডার্ক গ্রে': '#4a5568',
			'light gray': '#cbd5e0', 'light grey': '#cbd5e0', 'লাইট গ্রে': '#cbd5e0',
			'coffee': '#654321', 'coffee brown': '#4b3621', 'কফি': '#4b3621', 'কফি ব্রাউন': '#4b3621',
			'brown': '#744210', 'বাদামী': '#744210', 'বাদামি': '#744210',
			'navy': '#1a365d', 'navy blue': '#1a365d', 'নেভি': '#1a365d', 'নেভি ব্লু': '#1a365d',
			'maroon': '#742a2a', 'মেরুন': '#742a2a',
			'teal': '#319795', 'olive': '#556b2f', 'অলিভ': '#556b2f',
			'golden': '#d69e2e', 'গোল্ডেন': '#d69e2e', 'silver': '#a0aec0', 'সিলভার': '#a0aec0'
		};

		function resolveColorCode( val ) {
			if ( ! val ) return null;
			let clean = String( val ).trim().toLowerCase();
			try { clean = decodeURIComponent( clean ); } catch ( e ) {}
			clean = clean.replace( /[-_]/g, ' ' );
			if ( COLOR_PALETTE[ clean ] ) return COLOR_PALETTE[ clean ];
			if ( /^#[0-9a-f]{3,8}$/i.test( clean ) ) return clean;
			if ( window.CSS && CSS.supports && CSS.supports( 'color', clean ) ) return clean;
			return null;
		}

		function getMultiColorContainer() {
			let container = document.getElementById( 'swift-multi-color-container' );
			if ( ! container ) {
				container = document.createElement( 'div' );
				container.id = 'swift-multi-color-container';
				const variationsTable = variationForm.querySelector( 'table.variations' );
				if ( variationsTable && variationsTable.parentNode ) {
					variationsTable.parentNode.insertBefore( container, variationsTable.nextSibling );
				} else {
					variationForm.appendChild( container );
				}
			}
			return container;
		}

		function getAvailableColors() {
			const allSelects = Array.from( variationForm.querySelectorAll( 'select[data-attribute_name], select[name^="attribute_"]' ) );
			// 1. Look for a select whose name or label matches color
			const colorSelect = allSelects.find( function ( s ) {
				const row = s.closest( 'tr' );
				const lbl = row ? ( row.querySelector( 'th.label label, label' ) ? row.querySelector( 'th.label label, label' ).textContent : '' ) : '';
				let rawName = s.getAttribute( 'data-attribute_name' ) || s.name || '';
				try { rawName = decodeURIComponent( rawName ); } catch ( e ) {}
				return /color|colour|rang|কালার|রং/i.test( rawName + ' ' + lbl );
			} );
			if ( colorSelect ) {
				return Array.from( colorSelect.options )
					.filter( function ( o ) { return o.value !== ''; } )
					.map( function ( o ) { return { value: o.value, label: o.textContent.trim() }; } );
			}
			// 2. Fallback: select that is NOT package
			const nonPisSelect = allSelects.find( function ( s ) {
				const row = s.closest( 'tr' );
				const lbl = row ? ( row.querySelector( 'th.label label, label' ) ? row.querySelector( 'th.label label, label' ).textContent : '' ) : '';
				let rawName = s.getAttribute( 'data-attribute_name' ) || s.name || '';
				try { rawName = decodeURIComponent( rawName ); } catch ( e ) {}
				return ! /pis|pack|package|quantity|qty|প্যাকেজ|পিস/i.test( rawName + ' ' + lbl );
			} );
			if ( nonPisSelect ) {
				return Array.from( nonPisSelect.options )
					.filter( function ( o ) { return o.value !== ''; } )
					.map( function ( o ) { return { value: o.value, label: o.textContent.trim() }; } );
			}
			return [];
		}

		function updateMultiColorPickers( count ) {
			const container = getMultiColorContainer();
			container.innerHTML = '';
			if ( count < 2 ) {
				container.style.display = 'none';
				return;
			}
			container.style.display = 'block';

			const colors = getAvailableColors();
			if ( ! colors.length ) return;

			const bnOrdinal = [ '১ম', '২য়', '৩য়', '৪র্থ', '৫ম', '৬ষ্ঠ', '৭ম', '৮ম', '৯ম', '১০ম' ];

			for ( let i = 0; i < count; i++ ) {
				const wrapper = document.createElement( 'div' );
				wrapper.className = 'swift-extra-color-row';

				const label = document.createElement( 'label' );
				label.htmlFor = 'swift-color-pick-' + i;
				const ord = bnOrdinal[ i ] || ( ( i + 1 ) + 'তম' );
				label.innerHTML = '<strong>' + ord + ' পিসের কালার পছন্দ করুন:</strong>';

				const swatchRow = document.createElement( 'div' );
				swatchRow.className = 'swift-swatch-buttons swift-extra-swatches';
				swatchRow.setAttribute( 'role', 'group' );

				const hidden = document.createElement( 'input' );
				hidden.type = 'hidden';
				hidden.name = 'swift_colors[' + i + ']';
				hidden.id = 'swift-color-pick-' + i;

				colors.forEach( function ( color, cIdx ) {
					const btn = document.createElement( 'button' );
					btn.type = 'button';
					btn.className = 'swift-swatch-pill swift-color-swatch' + ( cIdx === 0 ? ' is-active' : '' );
					btn.dataset.value = color.value;
					btn.dataset.label = color.label;
					btn.setAttribute( 'aria-pressed', cIdx === 0 ? 'true' : 'false' );

					const colorCode = resolveColorCode( color.label ) || resolveColorCode( color.value );
					let dotHtml = '';
					if ( colorCode ) {
						dotHtml = '<span class="swift-swatch-dot" style="background-color:' + colorCode + ';"></span>';
					}

					btn.innerHTML = dotHtml +
						'<span class="swift-swatch-text">' + color.label + '</span>' +
						'<span class="swift-swatch-check" aria-hidden="true">✓</span>';

					btn.addEventListener( 'click', function ( e ) {
						e.preventDefault();
						swatchRow.querySelectorAll( '.swift-swatch-pill' ).forEach( function ( b ) {
							b.classList.remove( 'is-active' );
							b.setAttribute( 'aria-pressed', 'false' );
						} );
						btn.classList.add( 'is-active' );
						btn.setAttribute( 'aria-pressed', 'true' );
						hidden.value = color.value;

						// If 1st piece color clicked, sync with main color select
						if ( i === 0 ) {
							const mainColorSelect = variationForm.querySelector( 'select[data-attribute_name*="color"], select[name*="color"], select[data-attribute_name*="colour"], select[name*="colour"], select[data-attribute_name*="কালার"], select[data-attribute_name*="রং"]' );
							if ( mainColorSelect && mainColorSelect.value !== color.value ) {
								mainColorSelect.value = color.value;
								mainColorSelect.dispatchEvent( new Event( 'change', { bubbles: true } ) );
								if ( window.jQuery ) window.jQuery( mainColorSelect ).trigger( 'change' );
								const mainRow = mainColorSelect.closest( 'tr' ) || mainColorSelect.closest( '.value' ) || mainColorSelect.parentElement;
								if ( mainRow ) {
									mainRow.querySelectorAll( '.swift-swatch-pill' ).forEach( function ( mb ) {
										if ( mb.dataset.value === color.value ) {
											mb.classList.add( 'is-active' );
											mb.setAttribute( 'aria-pressed', 'true' );
										} else {
											mb.classList.remove( 'is-active' );
											mb.setAttribute( 'aria-pressed', 'false' );
										}
									} );
								}
							}
						}
					} );

					swatchRow.appendChild( btn );
				} );

				// Default to first color
				if ( colors.length ) {
					hidden.value = colors[ 0 ].value;
				}

				wrapper.appendChild( label );
				wrapper.appendChild( swatchRow );
				wrapper.appendChild( hidden );
				container.appendChild( wrapper );
			}
		}

		/* ------------------------------------------------------------------
		 * Swatch Selection — triggers native WooCommerce & jQuery change
		 * ------------------------------------------------------------------ */
		function selectSwatch( select, container, activeBtn, labelDisplay, attrTitle, combinedName ) {
			container.querySelectorAll( '.swift-swatch-pill' ).forEach( function ( b ) {
				b.classList.remove( 'is-active' );
				b.setAttribute( 'aria-pressed', 'false' );
			} );
			activeBtn.classList.add( 'is-active' );
			activeBtn.setAttribute( 'aria-pressed', 'true' );

			// Update native select
			select.value = activeBtn.dataset.value;

			// Update label display
			const selectedText = activeBtn.dataset.label || activeBtn.dataset.value;
			if ( labelDisplay ) {
				labelDisplay.innerHTML = attrTitle
					? '<span class="swift-attr-name">' + attrTitle + ':</span> <strong class="swift-attr-val">' + selectedText + '</strong>'
					: '<strong class="swift-attr-val">' + selectedText + '</strong>';
			}

			// Fire native event
			select.dispatchEvent( new Event( 'change', { bubbles: true } ) );

			// Fire jQuery event for WooCommerce core variation engine
			if ( window.jQuery ) {
				window.jQuery( select ).trigger( 'change' );
			}

			// If pis/package button clicked, update multi-color selectors
			const isPis = /pis|pack|package|quantity|qty|প্যাকেজ|পিস|পরিমাণ/i.test( combinedName );
			if ( isPis ) {
				const count = extractCount( activeBtn.dataset.value ) || extractCount( activeBtn.dataset.label );
				if ( ! isNaN( count ) && count >= 1 && count <= 10 ) {
					updateMultiColorPickers( count );
				}
			}
		}

		/* ------------------------------------------------------------------
		 * Build Swatches from native <select> elements
		 * ------------------------------------------------------------------ */
		const selects = variationForm.querySelectorAll( 'select[data-attribute_name], select[name^="attribute_"]' );

		selects.forEach( function ( select ) {
			// Find appropriate cell wrapper (prefer .value or td over raw tr)
			const wrapper = select.closest( '.value' ) || select.closest( 'td' ) || select.parentElement;
			const row = select.closest( 'tr' );
			const labelElem = row ? row.querySelector( 'th.label label, label' ) : null;
			const attrTitle = labelElem ? labelElem.textContent.replace( /[:：]/g, '' ).trim() : '';
			let attrName = select.getAttribute( 'data-attribute_name' ) || select.getAttribute( 'name' ) || '';
			try { attrName = decodeURIComponent( attrName ); } catch ( e ) {}
			const combinedName = ( attrName + ' ' + attrTitle ).toLowerCase();

			const isPis = /pis|pack|package|quantity|qty|প্যাকেজ|পিস|পরিমাণ/i.test( combinedName );
			const isColor = /color|colour|rang|কালার|রং/i.test( combinedName );

			// Hide native select visually (DOM presence preserved for WooCommerce scripts)
			select.style.cssText = 'position:absolute;width:1px;height:1px;overflow:hidden;opacity:0;pointer-events:none;';
			select.setAttribute( 'aria-hidden', 'true' );

			// Active attribute label feedback
			let labelDisplay = wrapper.querySelector( '.swift-swatch-label' );
			if ( ! labelDisplay ) {
				labelDisplay = document.createElement( 'div' );
				labelDisplay.className = 'swift-swatch-label';
				labelDisplay.setAttribute( 'aria-live', 'polite' );
				wrapper.appendChild( labelDisplay );
			}

			// Button container
			let btnContainer = wrapper.querySelector( '.swift-swatch-buttons' );
			if ( ! btnContainer ) {
				btnContainer = document.createElement( 'div' );
				btnContainer.className = 'swift-swatch-buttons ' + ( isPis ? 'swift-pis-buttons' : 'swift-color-swatches' );
				btnContainer.setAttribute( 'role', 'group' );
				btnContainer.setAttribute( 'aria-label', attrTitle || attrName.replace( /attribute_/i, '' ) );
				wrapper.appendChild( btnContainer );
			} else {
				btnContainer.innerHTML = '';
			}

			const options = Array.from( select.options ).filter( function ( o ) { return o.value !== ''; } );

			options.forEach( function ( option ) {
				const btn = document.createElement( 'button' );
				btn.type = 'button';
				btn.className = 'swift-swatch-pill ' + ( isPis ? 'swift-pis-btn' : 'swift-color-swatch' );
				btn.dataset.value = option.value;
				btn.dataset.label = option.textContent.trim();
				btn.setAttribute( 'aria-pressed', 'false' );

				// Color dot if attribute is color and matches known color
				const colorCode = isColor ? ( resolveColorCode( option.textContent ) || resolveColorCode( option.value ) ) : null;
				let dotHtml = '';
				if ( colorCode ) {
					dotHtml = '<span class="swift-swatch-dot" style="background-color:' + colorCode + ';"></span>';
				}

				// Always display text label & checkmark (never wipe text!)
				btn.innerHTML = dotHtml +
					'<span class="swift-swatch-text">' + option.textContent.trim() + '</span>' +
					'<span class="swift-swatch-check" aria-hidden="true">✓</span>';

				if ( option.disabled ) {
					btn.disabled = true;
					btn.setAttribute( 'aria-disabled', 'true' );
					btn.classList.add( 'is-disabled' );
				}

				btn.addEventListener( 'click', function ( e ) {
					e.preventDefault();
					selectSwatch( select, btnContainer, btn, labelDisplay, attrTitle, combinedName );
				} );

				btnContainer.appendChild( btn );
			} );

			// Auto-select first enabled option
			const firstEnabled = options.find( function ( o ) { return ! o.disabled; } );
			if ( firstEnabled ) {
				const firstBtn = Array.from( btnContainer.querySelectorAll( '.swift-swatch-pill' ) )
					.find( function ( b ) { return b.dataset.value === firstEnabled.value; } );
				if ( firstBtn ) {
					selectSwatch( select, btnContainer, firstBtn, labelDisplay, attrTitle, combinedName );
				}
			}
		} );

		/* ------------------------------------------------------------------
		 * Keep Buy Now button in sync with variation found events
		 * ------------------------------------------------------------------ */
		if ( window.jQuery ) {
			window.jQuery( variationForm ).on( 'found_variation', function ( event, variation ) {
				const buyNowBtn = variationForm.querySelector( '.swift-buy-now-btn' );
				if ( buyNowBtn && variation && variation.variation_id ) {
					buyNowBtn.dataset.variationId = variation.variation_id;
				}
			} );
		}
	}

	/* ------------------------------------------------------------------
	 * Initialization on DOMContentLoaded & pageshow
	 * ------------------------------------------------------------------ */
	if ( document.readyState === 'loading' ) {
		document.addEventListener( 'DOMContentLoaded', initVariations );
	} else {
		initVariations();
	}

	window.addEventListener( 'pageshow', function ( e ) {
		if ( e.persisted ) {
			const buyBtns = document.querySelectorAll( '.swift-buy-now-btn' );
			buyBtns.forEach( function ( btn ) {
				btn.disabled = false;
				btn.classList.remove( 'is-loading' );
			} );
		}
	} );

} )();
